WITH transactions_by_account AS (SELECT account_id, MIN(txn_time) first_txn_time, COUNT(CASE WHEN txn_type = 'CREDIT' THEN 1 END) credit_count FROM transactions WHERE account_id IN (2, 21) GROUP BY account_id) SELECT a.account_type, tba.first_txn_time, tba.credit_count FROM accounts a JOIN transactions_by_account tba ON a.id = tba.account_id ORDER BY account_type, tba.first_txn_time DESC
